import random


def generate(seed: int = 0) -> list[str]:
    """All generated arguments stay within the statement bounds and follow the problem guarantees."""
    r = random.Random(seed)
    cases = [("egg", "add"), ("foo", "bar"), ("paper", "title")]
    seen = set(cases)
    while len(cases) < 600:
        n = r.randint(1, 40)
        p = (
            "".join(r.choice("abcdef") for _ in range(n)),
            "".join(r.choice("uvwxyz") for _ in range(n)),
        )
        if p not in seen:
            seen.add(p)
            cases.append(p)
    return [f"candidate(s={a!r}, t={b!r})" for a, b in cases]


_BASE_GENERATE = generate
_BOUNDARY_CALLS = [
    "candidate(s='', t='')"
]


def generate(seed: int = 0) -> list[str]:
    calls = _BASE_GENERATE(seed)
    return calls + [call for call in _BOUNDARY_CALLS if call not in calls]
